# DbDataGateway's suite reads DBDATAKIT_TEST_MSSQL_SERVER / _USER / _PASSWORD and DBDATAKIT_TEST_POSTGRES (all printed by `env`); each engine has a switch that makes a missing server a failure instead of a skip.
DBDATAKIT_TEST_REQUIRE_SQLSERVER = true if DBDATAKIT_TEST_MSSQL
DBDATAKIT_TEST_REQUIRE_POSTGRES = true if DBDATAKIT_TEST_POSTGRES
